import {castSceneV39} from './cast-v39.js';
// Thirty original workplace scenes, adapted from a small set of form/KPI/budget motifs.
// Disputed amounts become reconciliation and approval questions, never findings of misconduct.
const rows=[
 ["white-team-budget","五千元核對到第三次，還沒輪到句點","白隊工作結束，你帶著屎潘蛇同意補助五千元的訊息來問Janet。第一趟她要名單，第二趟要簽名，今天又說少一張當時沒提的彙總。你問能否一次列完，她把剛補齊的資料推回來：先把這次要的補好再說。金額沒有變，來回的人已經快繞出一場運動會。","我現在看到缺這個，你先補；還有沒有其他的，送來再看。","核准金額與實際收款","一次列明的撥款條件","替五千元辦集點卡，每退件一次蓋章，集滿十格請它自己來上班。","Janet看著集點卡，說你有空畫這個不如先補表。旁邊的人卻開始替前幾趟補蓋章，她才拿出完整清單；五千元沒被你判成誰拿走，只是終於不用靠退件揭曉下一關。",[]],
 ['wine-ledger','一萬二，不能只寫大家知道','活動結束後，你整理到一筆一萬二的酒水募款，旁邊只有「大家知道」四個字。Janet問哪些是認捐、哪些已入帳，你發現兩張清單的日期和人數都不同。今天要補的是帳，不是找一個人替整群人的記憶負責。','認捐不能直接當收到，收到也還要對支出。','募款收入與活動支出','逐筆收支對照','替大家知道開一個銀行帳戶，看看它到底收過幾筆。','虛構帳戶一毛錢都沒有，大家卻開始交出各自的轉帳與收據。Janet把未確認的項目分開列出，這次的結餘沒有靠最大聲的人口算。',['finance','accounting']],
 ['approval-handoff','這筆現在歸真真，現在是什麼時候','你追一筆活動款，Janet說後續改由真真接手；真真說她只接到活動名單，沒接到付款責任。你看著兩人之間的空白交接欄，突然理解為什麼這筆小錢需要三位成年人站著開會。','換窗口可以，交接日期跟未辦項目要一起換。','付款主責與交接日期','雙方確認的交接單','替待辦款買一張單程票，禁止它在兩張辦公桌之間來回觀光。','紙車票釘在交接單上，Janet和真真各確認了自己負責的部分。錢還沒因為你畫車票就入帳，但你終於知道下一次應該問誰。',[],['janet','jenjen']],
 ['fixed-drink','慰勞飲料，甜度由上面決定','Janet傳來工作人員的慰勞飲料名單，品項、甜度、冰塊全選好了。你是行政，負責發飲料，還得解釋為什麼對乳製品不適的人也領到同一杯。名單寫體貼，現場卻很像在配發制服。','不要又變成我一杯一杯重問，先確認不能喝的人。','飲品需求與可替換份數','本人確認的領取表','讓每杯飲料先面試，答不出過敏原的不得錄取。','飲料面試沒有真的舉行，你卻抓出幾杯根本不能給原領取人。Janet同意先調整那幾份，慰勞終於不必靠員工自己買解藥。',['admin']],
 ["group-message","說明已發送，意思恕不附贈","活動款還在核對，Janet群發一句已依流程辦理。你問這代表已付款還是正在等，她說信裡都寫了；你把原句念一次，她又說不要只看字面。十二個視窗同時追問，你終於知道一句看起來有回答的話，也能把所有答案留在作者心裡。","我的意思不是寫得很清楚了嗎？你們不要自己想太多。","公告原句與付款進度","可直接回答已付或未付的狀態表","替群發信裝字幕機，左邊播原文，右邊請作者現場翻譯。","Janet先說不用弄得這麼麻煩，你把字幕停在已付或未付兩個選項。她終於指出目前還在等哪個確認，十二個視窗第一次收到同一個意思，不必再各自報名閱讀測驗。",[]],
 ['three-day-plan','三天交方針，市場今天才通知','Janet轉來部門的新營收KPI，請你三天內交商務開發方針。你問鎖定哪個市場、能用多少預算，她說先交方向。你看著原本排好的工作，覺得公司把市場研究誤認成了三日宅配。','先列出現在有什麼，缺什麼別寫成已經有。','新增目標與可用資源','三天內可完成的工作表','把開發方針放進發芽機，三天後只交一盆尚未成交的綠豆。','綠豆不會簽約，倒是讓會議承認三天只夠整理起點。Janet收到一份分階段計畫，你沒有為了準時把陌生人全部寫成準客戶。',['bd']],
 ['commission-blank','業績要背，獎金先空著','你被要求簽下新的業績目標，獎金算法那一頁卻還沒做好。Janet說可以先看成本，你問做到之後怎麼算，收到一句以後再討論。你原本是來對數字，現在像在購買一張尚未公布獎項的彩票。','目標、認列跟獎金規則要放在同一張桌上談。','業績認列與獎金規則','雙方確認的計算方式','拿空白獎金表去換空白業績表，提議雙方都保有想像空間。','你把兩張空白並排，會議安靜了幾秒。Janet先列出能確認的項目，未定的留待核准；你的簽名沒有替一份未知算法蓋章。',['sales','bd','hr']],
 ['pipeline-income','有興趣，尚未成為收入','Janet請你解釋本月業績表，表上把客戶說有興趣的案子全部加進收入。你把案件狀態一列，發現那不是同一件事；另一份主管的樂觀預估，像是用了不同的計算機。','預估可以留，但不要混進已成立的那一欄。','商機預估與收入認列','案件狀態及合約紀錄','把有興趣印成鈔票，先請販賣機測試是否接受。','販賣機沒有加入公司願景，紙鈔也沒買到咖啡。Janet讓你把預估另列，業務還能追案，帳上不必先替客戶付錢。',['accounting','sales']],
 ["retroactive-kpi","新規則昨天出生，今天嫌你上季沒遵守","人資請你整理上季考核，Janet送來昨天才更新的KPI。你指出通知日期，她說本來就應該知道，不要拿沒有寫下來當理由。表上每格都很整齊，只有規則何時告知那一欄剛好沒有設計。","標準現在整理出來而已，不代表以前就不用做到吧。","考核適用期間與告知時間","歷次版本和通知紀錄","替新KPI辦出生登記，請它先證明自己去年已經會走路。","Janet說這是態度問題，不是戶政問題。你把出生日期貼回通知信，她還是不高興，但昨天才出現的指標被分開標記，沒有順手拿來替上季打分。",["hr"]],
 ['seventh-floor-form','七樓表單，重開機第幾次','你陪Janet確認完一份業務表單，紅茶和阿福又帶著新的欄位來到七樓。阿福說只是小改，紅茶說順便統一，Janet把上次逐欄講過的檔案再開一次。你還沒坐下，已經聽出這場會議有熟悉的片頭曲。','先講這次新增哪一格，別整份再從頭跑。','本次變更與原先共識','有差異標記的表單','在會議門口裝讀檔點，答對上次結論才能進下一關。','你用三個問題當讀檔門檻，阿福才發現其中兩項上次已經決定。Janet只重談真正改動的欄位，七樓今天少播放了半場前情提要。',['finance','accounting','admin'],['janet','sophie','sonny']],
 ['other-field','其他事項，長得比本職還高','Janet請你把行政表單的其他事項整理一下。你往下拉，裡面已經包含招募、報到、薪資資料和幫主管訂位，主項只剩一行收發信件。職稱沒有變，其他卻像一間正在併購你的公司。','其他不能永遠不分類，做的人跟核准的人都要寫。','行政與人資的工作界線','實際任務及負責人清單','替其他事項申請獨立樓層，請它自己招募一個部門。','其他沒有租到樓層，你卻把人資事項拆回明確的窗口。Janet看見真正的工作量，這張表不再靠兩個字容納另一份全職工作。',['admin','hr']],
 ["signature-maze","退件理由一次只開放一格","你報一筆文具費，Janet第一次說少使用部門簽名，你補齊後，她又指著另一角說主管要先簽這裡。你問能否把整條路線列出來，她說照規定走就不會錯，卻沒有告訴你規定放在哪裡。發票金額不大，補件倒像有無限續關。","你先照我這次圈的改，其他的等送來看過再說。","費用類別與必要簽核","完整的核准流程","把核銷單折成大富翁棋盤，每到Janet這格就抽一張全新退件卡。","Janet說流程不是遊戲，你翻到第三張退件卡，問終點能不能先畫出來。她終於把剩下簽名一次圈齊，文具沒有變高級，報帳的人倒是差點走完一場職涯。",[]],
 ['duplicate-request','同一張發票，有兩個很急','Janet發現兩個部門各送了一次付款申請，附件是同一張發票。兩邊都說自己只是照流程，還各加上一個急字。你做會計，今天的任務是阻止一筆支出靠焦慮繁殖。','先核對原始單號，不要用兩份申請算兩次。','原始支出與重複申請','唯一付款編號','請兩份很急互相猜拳，只准一份拿付款號碼牌。','號碼牌只發出一張，另一份改註重複並通知原申請人。Janet保留兩邊的送件紀錄，急字沒有成功把付款金額乘以二。',['accounting']],
 ['invoice-missing','會計可以入帳，不能召喚發票','業務拿來客戶會議的支出，想在月底前直接完成核銷。Janet問憑證在哪，群組開始傳餐廳照片、菜單和一張糊掉的刷卡明細。你第一次看見一份核銷附件這麼能勾起食慾。','先找能核對的支出依據，照片不要當正式憑證。','支出內容與缺漏憑證','補件及確認清單','把餐廳照片供在印表機上，看看能不能感召出發票。','印表機只吐出一張更大的菜，業務終於回去聯絡店家。Janet把待補項目分開處理，你不用為了補這份附件，就學會隔空取物。',['accounting','sales']],
 ['currency-month-end','報價是美金，憑證只剩金額','你準備月底對帳，Janet拿來一份海外合作請款。報價有幣別，申請單沒有；轉帳手續費又被併進服務費。三份數字都長得像真的，卻沒有一個可以直接相減。','幣別、費用和換算基準先分開。','外幣款項與換算方式','原始報價和匯款明細','辦一場幣別戶籍普查，沒有國籍的數字先住待確認區。','你替每欄補回幣別，手續費也搬回自己的位置。Janet終於拿到能核對的差額，這個月沒有靠匯率替表格變魔術。',['finance','accounting']],
 ['project-code','錢花在甲案，預算住在乙案','一筆專案支出被填到還有餘額的代碼，Janet問你實際用在哪裡。送件人說代碼都差不多，反正是同一家公司。你看著兩位專案負責人，覺得他們應該不會願意共用同一份超支說明。','有餘額不代表可以直接借它的名字。','實際用途與預算歸屬','專案代碼更正紀錄','要求每個預算代碼認親，沒有血緣的不准硬叫爸爸。','代碼沒有驗DNA，你們卻找到真正的費用歸屬。Janet把需要調整的預算送回核准，乙案今天沒被隔壁的花費突然收養。',['finance','project']],
 ['verbal-approval','翅膀點過頭，頭現在不在','主管催你付款，說翅膀昨天點頭了。Janet問有沒有留下確認，對方開始示範翅膀點頭的角度。你管資金，不管頸部動作辨識；付款日卻已經被人答應給供應商。','誰核准、核准多少，至少要能查到。','核准範圍與付款時間','核准人的明確回覆','寄一顆會點頭的彈簧玩偶去簽核，問它是否也有預算權。','玩偶點了一下午，銀行餘額毫無反應。Janet等到真正的確認才排款，示範點頭的人也補上了完整金額。',['finance']],
 ['payroll-cutoff','薪資已封表，口頭又要插播','你剛把薪資資料核對完，Janet收到一則要調整某位同事薪資的口頭轉達。生效日期、本人確認和核准附件都還沒齊，訊息最後卻寫今天一定要處理。你手上的核對工作忽然像一個可以跳過所有問題的按鈕。','先補齊生效依據，不要拿一句很急改掉已確認的資料。','薪資異動內容與生效依據','本人及核准窗口的確認紀錄','給薪資表裝一道機場安檢，口頭小抄不得隨身登機。','安檢圖示擋不住主管，但缺漏清單可以。Janet把未確認的異動退回補件，你沒有讓一則轉傳訊息直接變成同事帳戶裡的差額。',['hr','accounting']],
 ['departure-label','離場原因，三張表三種人生','你接到一份離場結算：人資表寫協議，交接表寫資遣，簽收頁又寫自行離職。Janet問款項要按哪份計算，你發現當事人甚至還沒看過最後那頁。三張紙正在替同一個人各過各的。','先讓本人知道內容，原因和款項不能各寫一套。','離場分類與結算項目','當事人確認的文件','請三張表參加同一人的身分辨認，禁止各自宣布不同結局。','表格沒有上法庭，你們先停下互相矛盾的送件。Janet把待確認項目列清，當事人拿到完整版本後再處理，紙上的故事沒有搶先替他決定。',['hr','finance']],
 ['laptop-receipt','電腦回來了，收到的人還在轉寄','法師請離場同事把電腦交給Janet；你協助辦交接，Janet卻說設備要由資訊窗口驗收。機器放在桌上，三方訊息都寫請對方確認，彷彿這台筆電只要還沒開機就不算真正存在。','收件和設備驗收分開記，別讓本人重跑一趟。','設備收件與後續驗收','有日期的簽收及轉交紀錄','替筆電掛上訪客證，要求每次轉桌都蓋入境章。','筆電沒去移民署，轉交紀錄卻把三個窗口接起來。法師和Janet確認各自的部分，離場同事不用因為少一個回覆又親送一次。',['admin','mis','hr'],['janet','erich']],
 ['final-salary-list','最後一筆薪水，不是失物招領大會','Janet請你整理離場結算附件，有人陸續補上門禁卡、文具、舊活動墊款和一條不知道誰借的線。你接的是結算資料，不是偵探委託；清單卻越長越像全公司趁同事離開時一起清抽屜。','結算項目和待查物品分開，別讓沒有依據的東西混進去。','應付結算與其他待查事項','逐項有依據的明細','替每件待查物品設立證人席，說不出借給誰就先閉嘴。','那條線沒有作證，你們也沒有把猜測直接寫成扣款。Janet留下可確認的結算明細，其他物品各找原窗口，離場沒有順便承包全公司的健忘。',['hr','accounting']],
 ['stay-plan','留下來的計畫，不能只有留下來','同事提出想走，Janet請你協助留才，說工作可以再調整。你問要少掉哪些任務、由誰接、何時開始，會議卻只有一張寫著希望你留下的便利貼。人資的難題是把感情留住之前，至少先把工時算清楚。','要談留下，先拿出真的會改的安排。','留任條件與調整日期','本人可確認的工作安排','把留下來三個字製成辦公椅，請它自己完成原本的工作量。','紙椅承受不了一份報表，大家總算開始談要移出的任務。Janet帶走一份待核准安排，當事人還有選擇，沒有因為被感動就自動撤回自己的決定。',['hr']],
 ['cindy-vacancy','辛蒂留下空位，沒有留下分身術','辛蒂不在之後，有幾項跨部門待辦被送到Janet桌上，再轉到你手裡。你以為只要幫忙收件，打開卻是整季追蹤和主管會議。座位少了一張，工作量倒是沒有跟著請假。','交接要連同權限和工時談，不是轉寄完就結束。','空缺工作與暫代範圍','有期限的代理分工','辦一場空椅子徵才，請每項沒人接的工作輪流面試它。','空椅子一句也沒答，待辦卻因此攤開了真正的大小。Janet把需要主管決定的項目帶回去，你留下明確的暫代範圍，沒有靠職稱普通就免費升級成萬用主管。',['admin','hr']],
 ['training-budget','溝通課上完，責任沒有比較好溝通','公司想安排溝通課，Janet請你估訓練費用。各主管都說課很重要，問到誰有空參加、誰支援工作，又同時變得很會沉默。你協助估完費用，已經能預見最後只剩自己最有溝通能力，也最沒時間上課。','先確認參加人和代理安排，再報費用。','訓練名額與工作代理','確認過的出席及預算表','讓溝通課的第一堂先教主管怎麼回答誰來代班。','老師還沒進公司，出席表已經替大家上了第一課。Janet拿到可執行的費用，課程沒有再用一句都去學學，把整個下午的工作留給沒去的人。',['admin','hr']],
 ['helpdesk-priority','同一個故障，兩種服務溫度','Janet的列印問題剛處理完，你拿著相同錯誤畫面找阿福，得到一句先等。Janet也看見你的單，問是不是同一台機器。你不是非得立刻被服務，只想知道優先順序是故障等級，還是走過來的人。','要排隊可以，把急件條件跟處理狀態寫清楚。','報修優先級與等待順序','相同標準的工單紀錄','替印表機裝體溫計，每次態度降溫就自動印出排隊號碼。','體溫計沒有接上驅動程式，兩張工單倒是排到同一套順序。Janet等你一起確認列印，阿福今天不能只用語氣當處理進度。',[],['janet','sonny']],
 ['month-end-freeze','月底封帳，主管剛想到一筆','你剛完成本月帳務，Janet又收到一筆臨時支出，要塞進已關閉的報表。申請日期寫今天，說明卻要求當成前一週。你看著封帳通知，第一次覺得公司的時間有些人可以自由倒車。','把實際日期和調整原因留好，不要只改成看起來方便。','支出日期與報表調整','原始單據及調整紀錄','替月底裝一道旋轉門，想倒走的人先交一份時光旅行申請。','時光旅行沒有核准，Janet卻拿到可以追溯的調整說明。你依流程處理那筆支出，報表沒靠改日期假裝它早就坐在這裡。',['accounting']],
 ['supplier-deposit','訂金等你，採購還沒開始','供應商說主管已經答應，今天要收到訂金；你打開內部申請，規格和交期都還沒確認。Janet請你查一下，業務又說不要讓關係難看。你只是核對付款資料，卻忽然被期待用匯款替整份採購補寫前半段。','先對清楚訂什麼、誰同意，再排付款。','採購條件與訂金核准','完整訂購及付款資料','請訂金先戴安全帽，合約地基沒好就不得進工地。','安全帽放在待補附件旁，供應商收到明確的補件要求。Janet把付款排在條件確認之後，今天沒有讓一筆訂金自己發展出整套採購內容。',['finance','admin']],
 ['forecast-bell','敲鐘簡報，現金流先不要打拍子','翅膀的上市願景剛傳進群組，Janet請你準備下一季資金預估。業務那份檔案把所有預計成交都放進月底可用現金，你把付款期限攤開，發現敲鐘聲跟薪資支付日暫時還對不上拍。','願景可以留，能動用的錢另算。','預計收入與資金時點','分情境現金流表','拿玩具鐘當收款機，每敲一下就問一次銀行有沒有進帳。','玩具鐘敲得很熱鬧，銀行不為所動。Janet把樂觀、一般和延後情境分開，簡報仍能談未來，付款安排開始看今天真的有什麼。',['finance']],
 ['owen-meeting','歐文來了，金額不必跟著提高音量','一筆活動收支還沒對完，歐文走進來說今天一定要講清楚。Janet把表翻到一半，旁邊的人已開始輪流補充自己聽說的版本。你翻開收支表，桌上最缺的不是氣勢，是每一筆對應的依據。','請一次講一筆，沒有確認的先標出來。','爭議款項與待查內容','逐筆核對及回覆紀錄','把會議音量接到投影機，證明分貝再高也不會增加一張收據。','投影機沒有真的接收怒氣，你們卻把傳聞和可核對項目拆開。歐文等到逐項回覆，Janet補列待查日期，今天的結果沒有由最會拍桌的人代算。',['accounting','finance'],['janet','owen']],
 ['wine-club-agenda','定期喝酒，臨時變成心得分享','Janet下班後邀你吃飯，說是一群喜歡喝酒的人定期聚會。你原以為能聊點上班以外的事，翅膀坐下後，話題卻一路變成公司願景。服務生在等點餐，你還在等誰先把讚美說完。','本來說吃飯，至少先讓大家點菜吧。','私人邀約與用餐安排','當晚確認的參加方式','把菜單當股東議程，提案讓雞腿擁有三分鐘發言權。','你替雞腿念完提案，Janet笑著把菜單傳下去。願景晚幾分鐘再談，你終於吃到熱菜；這頓飯沒有因此變成隔天的工作考核。',[],['janet','wing'],true]
];
